DECLARE @AuthorId BIGINT = (SELECT TOP 1 id FROM [user]);

INSERT INTO course (author_id, title, description, published_at, created_at)
SELECT
    @AuthorId,
    'Mock Course ' + CAST(value AS VARCHAR(10)),
    'Load testing course description',
    GETDATE(),
    GETDATE()
FROM GENERATE_SERIES(1, 10000);
